import re, glob, subprocess
tot=0; bad=[]
for f in sorted(glob.glob('S*/E*.md')):
    t=open(f).read()
    ents=re.findall(r'\*\*(\w+)\*\* \(([^)]+)\)\n\nSource: friend/(\w+) @ ([0-9a-f]{40})\n\n',t)
    tot+=len(ents)
    # frontmatter checks
    m=re.search(r'^summary: "(.*)"$',t,re.M)
    parts=t.split('---\n',2)
    para=parts[2].strip().split('\n\n')[0].strip() if len(parts)>2 else ''
    if not m or m.group(1)!=para: bad.append((f,'summary mismatch'))
    if not re.search(r'^title: "The One With ',t,re.M): bad.append((f,'title'))
    if not re.search(r'^status: (ongoing|complete)$',t,re.M): bad.append((f,'status'))
    for sp,ts,br,sha in ents:
        body=subprocess.run(['git','log','-1','--format=%B',sha],capture_output=True,text=True).stdout
        if 'Friend-Message: 1' not in body: bad.append((f,'not a friend msg '+sha[:8])); continue
        ep=re.search(r'Episode: (\S+)',body).group(1)
        if ep != f[:-3].replace('/','/'): bad.append((f,'episode mismatch '+sha[:8]+' '+ep))
        utt=body.split('Reply-To:',1)[1].split('\n\n',1)[1].rstrip('\n')
        seg=t.split('Source: friend/%s @ %s\n\n'%(br,sha))[1].split('\n\n')[0].rstrip('\n')
        if seg!=utt: bad.append((f,'text mismatch '+sha[:8]))
print('total entries in archive:',tot)
print('problems:',len(bad))
for x in bad[:15]: print('  ',x)
PYEOF
